// Swap OP and LOOKUP for each variation:
//   Variation 2 (Sum):   running += num,      lookup = running - k
//   Variation 5 (Mod k): running += num,      lookup = normalize(running % k)
//   Variation 6 (XOR):   running ^= num,      lookup = running ^ k

Map<T, Integer> map = new HashMap<>();
map.put(IDENTITY, 1);     // 0 for Sum/XOR; normalize(0 % k) = 0 for Mod k
T running = IDENTITY;
int count = 0;

for (int num : nums) {
    running = OP(running, num);                          // update running aggregate
    count  += map.getOrDefault(LOOKUP(running, k), 0);   // query BEFORE insert
    map.merge(running, 1, Integer::sum);                 // always insert AFTER query
}

