// For each query (l, r): iterate and sum -- TLE for large inputs
int rangeSum(int[] nums, int l, int r) {
    int sum = 0;
    for (int i = l; i <= r; i++) sum += nums[i];
    return sum;  // O(n) per query => O(n*q) total for q queries
}

int[] buildPrefix(int[] nums) {
    int n = nums.length;
    int[] prefix = new int[n + 1];     // 0-padded sentinel at index 0
    for (int i = 0; i < n; i++)
        prefix[i + 1] = prefix[i] + nums[i];
    return prefix;
}

int rangeSum(int[] prefix, int l, int r) {
    return prefix[r + 1] - prefix[l];  // O(1) -- single subtraction
}

