// Intuition: result[i] = product of all elements to the left of i
//            times product of all elements to the right of i.
// Left pass builds the prefix products; right pass multiplies in suffix.
int[] productExceptSelf(int[] nums) {
    int n = nums.length;
    int[] res = new int[n];
    res[0] = 1;
    for (int i = 1; i < n; i++)        // left pass: prefix product
        res[i] = res[i-1] * nums[i-1];
    int right = 1;
    for (int i = n-1; i >= 0; i--) {  // right pass: multiply suffix
        res[i] *= right;
        right *= nums[i];
    }
    return res;
}

// Intuition: total = leftSum + nums[i] + rightSum
// When leftSum == rightSum => nums[i] is the pivot.
// We don't need a rightSum array: rightSum = total - prefix[i+1]
int pivotIndex(int[] nums) {
    int n = nums.length;
    int[] prefix = new int[n + 1];
    for (int i = 0; i < n; i++) prefix[i+1] = prefix[i] + nums[i];
    int total = prefix[n];
    for (int i = 0; i < n; i++) {
        int leftSum  = prefix[i];
        int rightSum = total - prefix[i+1];
        if (leftSum == rightSum) return i;
    }
    return -1;
}

