int subarraySum_brute(int[] nums, int k) {
    int count = 0, n = nums.length;
    for (int i = 0; i < n; i++) {
        int sum = 0;
        for (int j = i; j < n; j++) {
            sum += nums[j];
            if (sum == k) count++;  // O(n^2) time, O(1) space -- TLE
        }
    }
    return count;
}

int subarraySum(int[] nums, int k) {
    Map<Integer,Integer> map = new HashMap<>();
    map.put(0, 1);       // CRITICAL: base case -- empty prefix seen once
    int prefixSum = 0, count = 0;
    for (int num : nums) {
        prefixSum += num;
        // How many prior prefixes had value (prefixSum - k)?
        count += map.getOrDefault(prefixSum - k, 0);
        map.merge(prefixSum, 1, Integer::sum);  // insert AFTER querying
    }
    return count;  // TC: O(n)   SC: O(n)
}

