// Intuition: Same as count template, but we want maximum length.
// Store the FIRST index at which each prefix sum appears.
// When we see prefixSum - k in the map, the distance is i - map[prefixSum - k].
int longestSubarray(int[] nums, int k) {
    Map<Integer,Integer> map = new HashMap<>();
    map.put(0, -1);   // sentinel: prefix 0 exists before index 0
    int prefixSum = 0, maxLen = 0;
    for (int i = 0; i < nums.length; i++) {
        prefixSum += nums[i];
        if (map.containsKey(prefixSum - k))
            maxLen = Math.max(maxLen, i - map.get(prefixSum - k));
        map.putIfAbsent(prefixSum, i); // store FIRST occurrence only
    }
    return maxLen;  // TC: O(n)   SC: O(n)
}

// Intuition: Recode: odd -> 1, even -> 0. Then "k odd numbers in subarray"
// becomes "subarray sum = k" on the recoded array. Apply standard template.
int numberOfSubarrays(int[] nums, int k) {
    Map<Integer,Integer> map = new HashMap<>();
    map.put(0, 1);
    int prefixSum = 0, count = 0;
    for (int num : nums) {
        prefixSum += (num % 2);            // 1 if odd, 0 if even
        count += map.getOrDefault(prefixSum - k, 0);
        map.merge(prefixSum, 1, Integer::sum);
    }
    return count;  // TC: O(n)   SC: O(n)
}

