class NumMatrix {
    private int[][] P;

    NumMatrix(int[][] mat) {
        int m = mat.length, n = mat[0].length;
        P = new int[m+1][n+1];               // (m+1)x(n+1) with 0-border
        for (int i = 1; i <= m; i++)
            for (int j = 1; j <= n; j++)
                P[i][j] = mat[i-1][j-1]
                         + P[i-1][j]         // above
                         + P[i][j-1]         // left
                         - P[i-1][j-1];      // corner (added twice, subtract once)
    }

    int sumRegion(int r1, int c1, int r2, int c2) {
        // Inclusion-exclusion: big - top_strip - left_strip + top_left_corner
        return P[r2+1][c2+1]
             - P[r1][c2+1]
             - P[r2+1][c1]
             + P[r1][c1];
    }
    // Build: O(mn) | Query: O(1) | Space: O(mn)
}

// Intuition: Fix left and right columns (c1, c2). Then the "column sum" at
// each row r between c1..c2 is a 1D array. Apply Variation 2 on this 1D array.
// Row-wise prefix sums let us get column-strip sums in O(1).
int numSubmatrixSumTarget(int[][] mat, int target) {
    int m = mat.length, n = mat[0].length, count = 0;
    // Build row-wise prefix sums in-place
    for (int[] row : mat)
        for (int j = 1; j < n; j++) row[j] += row[j-1];

    for (int c1 = 0; c1 < n; c1++) {          // fix left column
        for (int c2 = c1; c2 < n; c2++) {     // fix right column
            Map<Integer,Integer> map = new HashMap<>();
            map.put(0, 1);
            int colSum = 0;
            for (int r = 0; r < m; r++) {
                // column strip sum from c1 to c2 in row r
                colSum += mat[r][c2] - (c1 > 0 ? mat[r][c1-1] : 0);
                count += map.getOrDefault(colSum - target, 0);
                map.merge(colSum, 1, Integer::sum);
            }
        }
    }
    return count;  // TC: O(m*n^2)   SC: O(m)
}

// O(n*q) total for q updates -- TLE at n,q ~ 1e5
void rangeAdd_brute(int[] arr, int l, int r, int v) {
    for (int i = l; i <= r; i++) arr[i] += v;
}

int[] applyUpdates(int n, int[][] updates) {
    int[] diff = new int[n + 1];    // +1 guard: safe write to diff[r+1] when r = n-1
    for (int[] u : updates) {
        int l = u[0], r = u[1], v = u[2];
        diff[l]     += v;           // start effect at l
        diff[r + 1] -= v;           // cancel effect after r
    }
    // Reconstruct: prefix sum of diff array
    int[] result = new int[n];
    result[0] = diff[0];
    for (int i = 1; i < n; i++)
        result[i] = result[i-1] + diff[i];
    return result;  // TC: O(n + q)   SC: O(n)
}

