// Intuition: At each stop, passengers board or exit. Model as range update:
// trip [numP, from, to] => add numP at diff[from], subtract at diff[to].
// (passengers are gone AT stop "to", not "to+1")
boolean carPooling(int[][] trips, int capacity) {
    int[] diff = new int[1001];   // stops in [0, 1000]
    for (int[] t : trips) {
        diff[t[1]] += t[0];       // board at t[1]
        diff[t[2]] -= t[0];       // exit at t[2] (not in car anymore)
    }
    int cur = 0;
    for (int passengers : diff) {
        cur += passengers;
        if (cur > capacity) return false;
    }
    return true;  // TC: O(n + maxStop)   SC: O(maxStop)
}

