int subarraysDivByK(int[] nums, int k) {
    Map<Integer,Integer> freq = new HashMap<>();
    freq.put(0, 1);               // empty prefix: remainder 0
    int prefixSum = 0, count = 0;
    for (int num : nums) {
        prefixSum += num;
        // Java's % can return negative -- always normalize!
        int rem = ((prefixSum % k) + k) % k;
        count += freq.getOrDefault(rem, 0);
        freq.merge(rem, 1, Integer::sum);
    }
    return count;  // TC: O(n)   SC: O(k)
}

