// Intuition: Same as mod-k template, but we need at least 2 elements.
// Store the FIRST index where each remainder appears.
// If we see the same remainder at index j and first_index[rem] <= j-2, valid.
boolean checkSubarraySum(int[] nums, int k) {
    Map<Integer,Integer> firstIndex = new HashMap<>();
    firstIndex.put(0, -1);   // prefix 0 seen before index 0
    int prefixSum = 0;
    for (int i = 0; i < nums.length; i++) {
        prefixSum += nums[i];
        int rem = prefixSum % k;
        if (firstIndex.containsKey(rem)) {
            if (i - firstIndex.get(rem) >= 2) return true; // length >= 2
        } else {
            firstIndex.put(rem, i);   // store first occurrence only
        }
    }
    return false;  // TC: O(n)   SC: O(k)
}

