// Range XOR query -- O(1)
int[] buildXorPrefix(int[] nums) {
    int n = nums.length;
    int[] xp = new int[n + 1];   // xp[0] = 0 (XOR identity element)
    for (int i = 0; i < n; i++) xp[i+1] = xp[i] ^ nums[i];
    return xp;
}

int rangeXOR(int[] xp, int l, int r) { return xp[r+1] ^ xp[l]; }

// Count subarrays with XOR = k -- O(n)
// Intuition: need x such that xorSum ^ x = k => x = xorSum ^ k
int countSubarraysXorK(int[] nums, int k) {
    Map<Integer,Integer> map = new HashMap<>();
    map.put(0, 1);             // identity: empty prefix XOR = 0
    int xorSum = 0, count = 0;
    for (int num : nums) {
        xorSum ^= num;
        count += map.getOrDefault(xorSum ^ k, 0);  // lookup xorSum ^ k
        map.merge(xorSum, 1, Integer::sum);
    }
    return count;  // TC: O(n)   SC: O(n)
}

