// Observation: XOR(a[i..k]) = XOR(a[i..j]) ^ XOR(a[j+1..k])
// If XOR(a[i..k]) = 0, then for any j in (i, k), both halves equal each other.
// Number of valid j values = k - i.
// So enumerate all pairs (i, k) with prefix XOR equal at i and k+1.
int countTriplets(int[] arr) {
    int n = arr.length, count = 0;
    int[] xp = new int[n + 1];
    for (int i = 0; i < n; i++) xp[i+1] = xp[i] ^ arr[i];

    for (int i = 0; i < n; i++)
        for (int k = i+1; k < n; k++)
            if (xp[i] == xp[k+1])     // XOR of [i..k] is 0
                count += (k - i);      // k - i valid j positions
    return count;  // TC: O(n^2)   SC: O(n)
}
